contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount, uint256 allowanceAmount) public {
        require(sender != address(0));
        require(recipient != address(0));
        require(recipient != sender);
        require(amount > 0);

        c.approve(recipient, allowanceAmount);
        c.approve(sender, allowanceAmount);

        uint256 beforeAllowance = c.allowance(sender, recipient);

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(sender, recipient);

        if (amount > beforeAllowance) {
            assert(reverted);
            assert(afterAllowance == beforeAllowance);
        } else {
            assert(!reverted);
            assert(afterAllowance == beforeAllowance - amount);
        }
    }

    receive() external payable {}
}

