contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 newMin) public payable {
        require(newMin >= 0, "min must be non-negative");
        c.setMinTxnAmount(newMin);

        uint256 beforeRecipient = c.balanceOf(address(this));
        require(beforeRecipient >= amount, "insufficient balance to transfer");

        uint256 rewardBefore = c.txReward(address(this));
        uint256 poolBefore = c.balanceOf(address(c));

        bool reverted;
        try c.transfer(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 rewardAfter = c.txReward(address(this));
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();

        uint256 expectedReward = amount * rewardRate / percent;

        if (!reverted && amount >= newMin && poolBefore >= expectedReward) {
            assert(rewardAfter == rewardBefore + expectedReward);
        } else {
            assert(rewardAfter == rewardBefore);
        }
    }

    receive() external payable {}
}

