contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, address recipient, uint256 amount, uint256 allowanceAmount) public {
        require(spender != address(0));
        require(recipient != address(0));

        // Ensure the spender's allowance for this test contract is exactly allowanceAmount,
        // and that the contract has a balance of at least allowanceAmount.
        // If allowanceAmount is 0, transferFrom(amount) should revert for any amount > 0.
        c.approve(spender, allowanceAmount);

        uint256 beforeAllowance = c.allowance(address(this), spender);

        bool reverted;
        try c.transferFrom(address(this), recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);

        // Either the call reverted and the allowance is unchanged, or it succeeded and
        // the allowance decreased by exactly the amount. (When the allowance is
        // insufficient or the transfer fails, it must revert instead of silently changing
        // the allowance.)
        assert(reverted ? afterAllowance == beforeAllowance : afterAllowance + amount == beforeAllowance);
    }
}

