contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, address sender, address recipient, uint256 approveAmount, uint256 transferAmount) public {
        require(recipient != address(0), "recipient zero");
        require(sender != address(0), "sender zero");
        require(recipient != address(c), "recipient is contract");
        require(sender != address(c), "sender is contract");
        require(transferAmount > 0, "amount zero");
        require(transferAmount <= approveAmount, "amount exceeds approval");

        // fund sender through the owner path
        // msg.sender is holder of initial supply and owner
        c.transfer(sender, transferAmount);

        uint256 senderBalBefore = c.balanceOf(sender);
        uint256 recipientBalBefore = c.balanceOf(recipient);

        c.approve(sender, approveAmount);

        uint256 allowanceBefore = c.allowance(sender, spender);

        c.transferFrom(sender, recipient, transferAmount);

        uint256 senderBalAfter = c.balanceOf(sender);
        uint256 recipientBalAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(sender, spender);

        // sender cannot receive rewards because recipient is an allowed role; sender is not allowed role
        // recipient is uninitialized (allowed role false), so plain transfer path
        assert(senderBalBefore - senderBalAfter == transferAmount);
        assert(recipientBalAfter - recipientBalBefore == transferAmount);
        assert(allowanceBefore - allowanceAfter == transferAmount);
    }

    receive() external payable {}
}

