        // Setup: move some tokens from msg.sender (the deployer / owner) to the sender so it can transfer.
        c.transfer(sender, amount);

        uint256 senderBefore = c.balanceOf(sender);
        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) {
