        }

        if (!reverted) {
            uint256 senderAfter = c.balanceOf(sender);
            uint256 recipientAfter = c.balanceOf(recipient);

            // General rule: a successful transfer decreases the sender by exactly the transfer amount
            // and increases the recipient by exactly the transfer amount.
            assert(senderAfter == senderBefore - amount);
            assert(recipientAfter == recipientBefore + amount);
        } else {
            // If it reverted, c's state must have been left unchanged.
            assert(c.balanceOf(sender) == senderBefore);
            assert(c.balanceOf(recipient) == recipientBefore);
        }
    }

    receive() external payable {}
}

