    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "zero recipient");
        require(recipient != address(this), "self recipient");
        require(amount > 0, "zero amount");

        c.transfer(address(this), amount);

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);

        bool success;
        try c.transfer(recipient, amount) {
            success = true;
        } catch {
            success = false;
        }

        uint256 senderAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(recipient);

        assert(success && senderBefore >= amount && senderAfter == senderBefore - amount && recipientAfter == recipientBefore + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount) public {
        require(sender != address(0), "zero sender");
        require(recipient != address(0), "zero recipient");
        require(amount > 0, "zero amount");

        uint256 senderBefore = c.balanceOf(sender);
        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 senderAfter = c.balanceOf(sender);
            uint256 recipientAfter = c.balanceOf(recipient);
            assert(senderBefore - senderAfter == amount && recipientAfter - recipientBefore == amount);
        }
    }

    receive() external payable {}
}

