contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, address owner, address recipient, uint256 amount) public {
        require(spender != address(0));
        require(owner != address(0));
        require(recipient != address(0));
        require(owner != spender);
        require(owner != recipient);
        require(amount > 0);

        uint256 ownerBefore = c.balanceOf(owner);
        require(ownerBefore >= amount);

        bool approved = c.approve(spender, amount);
        require(approved);

        uint256 allowanceBefore = c.allowance(owner, spender);
        require(allowanceBefore == amount);

        uint256 spenderBefore = c.balanceOf(spender);
        uint256 recipientBefore = c.balanceOf(recipient);

        (bool ok, bytes memory data) = address(c).call(
            abi.encodeWithSignature(
                "transferFrom(address,address,uint256)",
                owner,
                recipient,
                amount
            )
        );
        require(ok, "transferFrom failed");
        require(data.length >= 32);

        bool returnedTrue;
        assembly {
            returnedTrue := mload(add(data, 0x20))
        }

        uint256 ownerAfter = c.balanceOf(owner);
        uint256 spenderAfter = c.balanceOf(spender);
        uint256 recipientAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(owner, spender);

        assert(
            returnedTrue &&
            ownerAfter == ownerBefore - amount &&
            recipientAfter == recipientBefore + amount &&
            spenderAfter == spenderBefore &&
            allowanceAfter == allowanceBefore - amount
        );
    }

    receive() external payable {}
}

