contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "recipient zero");
        require(amount > 0, "amount zero");

        uint256 balBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(recipient);
        uint256 supplyAfter = c.totalSupply();

        if (!reverted) {
            uint256 delta = balAfter >= balBefore ? balAfter - balBefore : 0;
            assert(delta >= amount && supplyAfter == supplyBefore);
        } else {
            assert(balAfter == balBefore && supplyAfter == supplyBefore);
        }
    }

    receive() external payable {}
}

