contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public {
        require(from != address(0) && to != address(0), "zero address");
        require(from != to, "self transfer");
        require(amount > 0, "zero amount");

        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);
        uint256 sumBefore = balFromBefore + balToBefore;

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balFromAfter = c.balanceOf(from);
        uint256 balToAfter = c.balanceOf(to);
        uint256 sumAfter = balFromAfter + balToAfter;

        // If the transfer reverted, balances must not change.
        // If it succeeded, the sum of the two balances must have either stayed the
        // same (plain transfer) or increased by a reward/mint amount, but never
        // decreased. Since rewardRate/percent are public and may be changed,
        // we only assert the non-decrease invariant here.
        assert(reverted ? (sumAfter == sumBefore) : (sumAfter >= sumBefore));
    }
}

