contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address sender, address recipient, uint256 amount) public {
        require(sender != address(0) && recipient != address(0), "zero address");

        // Set up allowance: sender must have at least `amount` tokens for transferFrom to succeed.
        uint256 bal = c.balanceOf(sender);
        require(bal >= amount, "sender balance insufficient");

        // Give the test contract an allowance from sender.
        c.approve(address(this), amount);
        // Wait: approve(msg.sender=address(this)) sets allowance[address(this)][address(this)]?
        // No: c.approve sets allowance[msg.sender][spender] = _allowances[address(this)][address(this)].
        // We need to call as sender. But the test contract is the only caller of c.
        // Hmm.

        // The test contract cannot impersonate sender. However, transferFrom gives allowance
        // from sender to msg.sender. The test contract can be the spender only if sender
        // approved it. We cannot call from sender. But we can make addresses(this) the sender
        // by using c.transfer? No.

        // The only way to make c.transferFrom succeed from address(this) is if _allowances[sender][address(this)] >= amount,
        // which we cannot set on behalf of sender because approve uses msg.sender.
        // So the rule with a precondition that sender == address(this) is needed.

        // However, sender as an arbitrary address would fail early. We can still assert a rule
        // about the case where sender can be any address but only when sender != address(this).
        // The precondition says sender is arbitrary. The call may revert. We can test a rule
        // that if it succeeds, the allowance decreased. But it will never succeed unless
        // sender == address(this) and there is an allowance.

        // We can test that transferFrom does not change allowance if sender != address(this)
        // and it will revert. That rule isn't interesting.

        // Let's instead choose a different approach: test that transferFrom with sender = address(this)
        // decreases the allowance of address(this) by exactly amount, provided allowance >= amount.
        // We set allowance by calling c.approve(address(this), amount) from address(this).

        require(sender == address(this), "sender must be the test contract");
        c.approve(recipient, amount);
        uint256 allowanceBefore = c.allowance(sender, recipient);

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 allowanceAfter = c.allowance(sender, recipient);
            assert(allowanceAfter == allowanceBefore - amount);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, address recipient, uint256 amount) public {
